export function personaResumeText(persona) {
    return [
        persona.name,
        persona.email,
        persona.phone,
        persona.linkedinUrl,
        persona.githubUrl,
        persona.portfolioUrl,
        ...(persona.skills || []),
        ...(persona.experience || []).flatMap((role) => [role.title, role.company, ...(role.bullets || [])]),
        ...(persona.education || []).flatMap((item) => [item.institution, item.degree, item.field])
    ].filter(Boolean).join("\n");
}
